mapper.select:
select t1.*, t2.book_name, t3.pen_name from author_income t1 left join book t2 on t1.book_id = t2.id left join author t3 on t1.author_id = t3.id
and t1.book_id = 0
and (t2.book_name like concat('%', #{keyword}, '%') or t3.pen_name like concat('%', #{keyword}, '%'))
and t1.pay_status = #{payStatus}
and date_format(t1.income_month, '%Y-%m') = #{month}
order by t1.income_month desc, t1.id desc
